sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
          /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
          /* Optional GlideRecord */ event) {

	var record = current;

	var baseSysId = record.getValue("sys_id");

	gs.info(baseSysId.toString());

	var grRegistrations = new GlideRecord("x_1584312_bases_registration");
	grRegistrations.addEncodedQuery("base=" + baseSysId.toString() + "^stateIN3");
	grRegistrations.query();

	var users = [];

	gs.info(users);

	while(grRegistrations.next()){
		template.print("<p>" + grRegistrations.opened_by.name + "</p>");
	}




})(current, template, email, email_action, event);
